create trigger followups_protect before insert or update on public.clinical_follow_ups for each row execute function public.protect_doctor_clinical_row();create trigger followups_updated before update on public.clinical_follow_ups for each row execute function public.set_updated_at();create trigger followups_event after insert or update on public.clinical_follow_ups for each row execute function public.clinical_event();
