revoke all on function public.is_diagnostic_member(public.provider_type,uuid),public.can_manage_clinical_booking(uuid),public.can_read_lab_result(public.lab_results),public.can_read_radiology_result(public.radiology_results),public.can_access_clinical_result_object(text,boolean) from public;grant execute on function public.is_diagnostic_member(public.provider_type,uuid),public.can_manage_clinical_booking(uuid),public.can_read_lab_result(public.lab_results),public.can_read_radiology_result(public.radiology_results),public.can_access_clinical_result_object(text,boolean) to authenticated;
